  add("hd", "to center " + fmt(g.x - (b.x0 + b.x1)/2) + " / " + fmt((b.y0 + b.y1)/2 - g.y) + " · to outline " + fmt(g.x - g.w/2 - b.x0) + " / " + fmt(g.y - g.h/2 - b.y0));
