    const m = lk.m.filter(r => r && Number.isInteger(r.pid) && Number.isInteger(r.sid)).map(r => ({ pid: r.pid, shape: Number.isInteger(r.shape) ? r.shape : 0, sid: r.sid, ...(Number.isFinite(r.len) && r.len > 0 ? { len: r.len } : {}) }));
    if (m.length > 1) out.push({ id: out.length + 1, len: Number.isFinite(lk.len) && lk.len > 0 ? lk.len : 0, m });
