{ const was = console.error; console.error = function (...a) { try { noteError(a.map(x => (x && x.message) || String(x)).join(" ")); } catch (x) {} return was.apply(console, a); }; }
// the bug information, as text (a promise: the desktop app is asked for the system's name)
