  if (UPD.st === "checking" || UPD.st === "downloading" || UPD.st === "ready") { if (manual) toast(UPD.st === "checking" ? "Checking already" : "Version " + UPD.found.version + " is " + (UPD.st === "ready" ? "downloaded: Restart to Update at the top right" : "being downloaded")); return Promise.resolve(null); }
