  const f = L[0] ? { ...L[0], k: "seg", at: segPt(L[0].sh, L[0].i, 0.5) } : g && g.sh.pts[S.selPt] ? { p: pr, sh: g.sh, kind: g.kind, int: g.j, i: S.selPt, k: "pt", at: g.sh.pts[S.selPt] } : null;
