/* The browser's own menu never opens inside the program (Round G1): a right-click anywhere on the page is the program's,
   whatever is under the pointer when the menu event comes (on Windows it comes when the button is let go, and by then one of
   our menus or a dialog may be under the pointer). Only a real text field keeps the browser's menu, for copy and paste, and a
   right-click only when the button also went down on a text field (not a dialog that opened under a right-click drag). */
const textField = (t) => !!t && (t.isContentEditable || t.tagName === "TEXTAREA" || (t.tagName === "INPUT" && /^(text|search|number|email|url|tel|password|)$/i.test(t.type || "")));
let rightOnText = false, rightTaken = false;
/* (Round r14 / 1) A right press while a drag in the 2D window goes on ("right click while editing to type exact measurements",
   the Moving Distance box: B1 p.11) is acted on as it goes down: the browser's menu event comes then on Linux but only when
   the button is let go on Windows, by which time the left button may be up too and the drag over. The menu event that
   follows, whenever it comes, is then swallowed (rightTaken; the next right press sets it afresh). */
window.addEventListener("mousedown", (e) => {                 // (mousedown: a right press while the left is held is no pointerdown)
  if (e.button !== 2) return;
  rightOnText = textField(e.target);
  rightTaken = e.target === cv && (e.buttons & 1) && S.drag && S.drag.k !== "pan" ? (cvMenu(e), true) : false;
}, true);
window.addEventListener("contextmenu", (e) => {
  if (rightTaken) { rightTaken = false; e.preventDefault(); e.stopImmediatePropagation(); return; }
  if (!(textField(e.target) && (rightOnText || e.button !== 2))) e.preventDefault();
}, true);
/* (Round r24) A BUTTON THAT OPENS A POPOVER CLOSES IT WITH A SECOND CLICK: a list of #menu (the mode drop-down, the display
   buttons, Print Layout's, the status bar's View and Recent, a size group's gear, Information Display, a 3D state's chip, …)
   or a panel that drops down (#dlg with the class drop: the Library). A press outside the popover closes it, as before,
   on its button too; the click that follows on that same button is then swallowed, so it does not open it again (the menu
   bar's titles do the same with barToggle). Which button opened the popover is seen from the click that opened it
   (popOwner); a click elsewhere, the popover's own rows and Esc work as before. */
let popOwner = null, popShut = null;
const popOpen = () => menu.style.display === "block" || (dlgOpen() && /\bdrop\b/.test(dlg.className));
const popButton = (t) => (t && t.closest ? t.closest("button") : null);
window.addEventListener("click", (e) => {
  const b = popButton(e.target);
  if (popShut && b === popShut) { popShut = null; e.stopImmediatePropagation(); if (e.preventDefault) e.preventDefault(); return; }
  popShut = null;
  // (after the click has been handled: some buttons stop it on its way, so no listener after theirs would see it)
  const was = popOpen();
  if (b && !inMenu(b) && !dlg.contains(b)) setTimeout(() => { if (!was && popOpen()) popOwner = b; }, 0);
}, true);
window.addEventListener("pointerdown", (e) => {
  popShut = popOwner && popOpen() && (popOwner === e.target || popOwner.contains(e.target)) ? popOwner : null;
  if (!popOpen()) popOwner = null;
  if (dlgOpen() && !dlg.contains(e.target)) hideDlg();
  if (!inMenu(e.target)) {
    // a press on the title of the menu-bar menu that is open closes it (the click that follows does not open it again)
    const t = e.target.closest ? e.target.closest(".mb") : null;
    barToggle = !!t && t === barOpen && menu.style.display === "block";
    hideMenu();
  }
  if (!e.target.closest(".slot") && !e.target.closest(".flyout")) closeFlyouts();
}, true);

