    for (let i = 0; i < m; i++) out += "v " + +X[3*i].toFixed(3) + " " + +X[3*i+1].toFixed(3) + " " + +X[3*i+2].toFixed(3) + "\n";
    if (xy && xy.length >= 2*m) for (let i = 0; i < m; i++) out += "vt " + +xy[2*i].toFixed(3) + " " + +(-xy[2*i+1]).toFixed(3) + "\n";
    const vt = xy && xy.length >= 2*m;
