  const dv = sub(to, V(b.x0, b.y0));
  push("Placement: " + PLACEMENTS.find(x => x[0] === how)[1]);
  for (const q of ps) mapPiece(q, (r) => add(r, dv));
  commit(); fitAll();
  return true;
