    const b = document.createElement("button"); b.title = n; b.innerHTML = svgIcon(icon); b.onclick = (e) => { e.stopPropagation(); const r = b.getBoundingClientRect(); listMenu(layoutSelector(g), r.right + 6, r.top); }; sel.appendChild(b);
