    if (!d) { const h = layoutAt(sx, sy); S.layHover = h ? h.key : null; lcv.style.cursor = h && !layoutOf().lock ? "move" : "default"; return drawLayout(); }
    if (d.pan) { S.lview.x = d.vx + sx - d.x; S.lview.y = d.vy + sy - d.y; lcv.style.cursor = "grabbing"; return drawLayout(); }
