  let left, top;
  if (row) { left = side(row.right + 2, row.left - 2, w, W); top = side(row.top - 5, row.bottom + 5, h, H); }
  else { left = side(x, x, w, W); top = above ? (y - 6 - h >= m ? y - 6 - h : side(y, y, h, H)) : side(y, y, h, H); }
