  const tabs = !bar && items.tabs, k = tabs && tab && tabs[tab] ? tab : "all";
  menuRows(menu, k === "all" ? items : tabs[k], 0, (rows) => listMenu(rows, x, y, above, bar));
  if (tabs) menuTabs(menu, items, x, y, above, k);
