      if (kind === "fabric" && k === "physical" && it[k] !== "Custom" && FABRIC_PHYS[it[k]]) { it.weight = FABRIC_PHYS[it[k]].weight; it.thickness = FABRIC_PHYS[it[k]].thickness; it.maxStretch = FABRIC_PHYS[it[k]].maxStretch; }
