      grain: +grainAngle(grainOf(p)).toFixed(1), shrink: p.shrink.w + " / " + p.shrink.h + " %",
      mirror: symmetricOf(p) ? "h" : inf.mirror || "", mirrorFixed: symmetricOf(p), cut: p.quantity, desc: inf.desc || "", stage: inf.stage || "",
