  const L = cum[cum.length - 1], a = L*(f0 || 0), b = L*(f1 === undefined ? 1 : f1), out = [];
  const at = (s) => { let k = 1; while (k < pts.length - 1 && cum[k] < s) k++; const f = cum[k] - cum[k-1] > 1e-9 ? (s - cum[k-1])/(cum[k] - cum[k-1]) : 0; return V(pts[k-1].x + (pts[k].x - pts[k-1].x)*f, pts[k-1].y + (pts[k].y - pts[k-1].y)*f); };
