    const it = G3.items.get(p.id), m = it.mesh, vs = list.filter(x => x.p === p).map(x => x.v);
    p.pins = (p.pins || []).filter(q => !vs.some(v => Math.hypot(q.x - m.xy[2*v], q.y - m.xy[2*v+1]) < m.res*0.6));
